					m1[e.Change == first.Change]*m2[e.Change < first.Change]*1) < 0 {
					es[0], es[i+1] = es[i+1], es[0]
					success = false
				}
			}
		}
		es = es[1:]
	}

	var s string
	if locale == "nl-NL" {
		s = "Datum" +
			strings.Repeat(" ", 10-len("Datum")) +
			" | " +
			"Omschrijving" +
			strings.Repeat(" ", 25-len("Omschrijving")) +
			" | " + "Verandering" + "\n"
	} else if locale == "en-US" {
		s = "Date" +
			strings.Repeat(" ", 10-len("Date")) +
			" | " +
			"Description" +
			strings.Repeat(" ", 25-len("Description")) +
			" | " + "Change" + "\n"
	} else {
		return "", errors.New("")
	}
	co := make(chan struct {
		i int
		s string
		e error
	})
	for i, et := range entriesCopy {
		go func(i int, entry Entry) {
			if len(entry.Date) != 10 {
				co <- struct {
					i int
					s string
					e error
				}{e: errors.New("")}
			}
			d1, d2, d3, d4, d5 := entry.Date[0:4], entry.Date[4], entry.Date[5:7], entry.Date[7], entry.Date[8:10]
			if d2 != '-' {
				co <- struct {
					i int
					s string
					e error
				}{e: errors.New("")}
			}
			if d4 != '-' {
				co <- struct {
					i int
					s string
					e error
				}{e: errors.New("")}
			}
			de := entry.Description
			if len(de) > 25 {
				de = de[:22] + "..."
			} else {
				de = de + strings.Repeat(" ", 25-len(de))
			}
			var d string
			if locale == "nl-NL" {
				d = d5 + "-" + d3 + "-" + d1
			} else if locale == "en-US" {
				d = d3 + "/" + d5 + "/" + d1
			}
			negative := false
			cents := entry.Change
			if cents < 0 {
				cents = cents * -1
				negative = true
			}
			var a string
			if locale == "nl-NL" {
				if currency == "EUR" {
					a += "€"
				} else if currency == "USD" {
					a += "$"
				} else {
					co <- struct {
						i int
						s string
						e error
					}{e: errors.New("")}
				}
				a += " "
				centsStr := strconv.Itoa(cents)
				switch len(centsStr) {
				case 1:
					centsStr = "00" + centsStr
				case 2:
					centsStr = "0" + centsStr
				}
				rest := centsStr[:len(centsStr)-2]
				var parts []string
				for len(rest) > 3 {
					parts = append(parts, rest[len(rest)-3:])
					rest = rest[:len(rest)-3]
				}
				if len(rest) > 0 {
					parts = append(parts, rest)
				}
				for i := len(parts) - 1; i >= 0; i-- {
					a += parts[i] + "."
				}
				a = a[:len(a)-1]
				a += ","
				a += centsStr[len(centsStr)-2:]
				if negative {
					a += "-"
				} else {
					a += " "
				}
			} else if locale == "en-US" {
				if negative {
					a += "("
				}
				if currency == "EUR" {
					a += "€"
				} else if currency == "USD" {
					a += "$"
				} else {
					co <- struct {
						i int
						s string
						e error
					}{e: errors.New("")}
				}
				centsStr := strconv.Itoa(cents)
				switch len(centsStr) {
				case 1:
					centsStr = "00" + centsStr
				case 2:
					centsStr = "0" + centsStr
				}
				rest := centsStr[:len(centsStr)-2]
				var parts []string
				for len(rest) > 3 {
					parts = append(parts, rest[len(rest)-3:])
					rest = rest[:len(rest)-3]
				}
				if len(rest) > 0 {
					parts = append(parts, rest)
				}
				for i := len(parts) - 1; i >= 0; i-- {
					a += parts[i] + ","
				}
				a = a[:len(a)-1]
				a += "."
				a += centsStr[len(centsStr)-2:]
				if negative {
					a += ")"
				} else {
					a += " "
				}
			} else {
				co <- struct {
					i int
					s string
					e error
				}{e: errors.New("")}
			}
			var al int
			for range a {
				al++
			}
			co <- struct {
				i int
				s string
				e error
			}{i: i, s: d + strings.Repeat(" ", 10-len(d)) + " | " + de + " | " +
				strings.Repeat(" ", 13-al) + a + "\n"}
		}(i, et)
	}
	ss := make([]string, len(entriesCopy))
	for range entriesCopy {
		v := <-co
		if v.e != nil {
			return "", v.e
		}
		ss[v.i] = v.s
	}
	for i := 0; i < len(entriesCopy); i++ {
		s += ss[i]
	}
	return s, nil
}

func TestDifferentialAgainstOriginal(t *testing.T) {
	amounts := []int{0, 1, 5, 99, 100, 101, 999, 1000, 1001, 12345, 123456, 999999, 1000000, 123456789,
		-1, -5, -99, -100, -101, -999, -1000, -12345, -123456, -999999, -1000000, -123456789}
	dates := []string{"2015-01-01", "2015-01-02", "2015-03-12", "2014-12-31", "2016-06-15"}
	descs := []string{"", "Buy present", "Get present", "Something", "Freude schoner Gotterfunken",
		strings.Repeat("a", 25), strings.Repeat("b", 26), strings.Repeat("c", 50)}
	currencies := []string{"USD", "EUR"}
	locales := []string{"en-US", "nl-NL"}

	n := 0
	for _, cur := range currencies {
		for _, loc := range locales {
			for _, amt := range amounts {
				for _, dt := range dates {
					for _, de := range descs {
						entries := []Entry{{Date: dt, Description: de, Change: amt}}
						got, gotErr := FormatLedger(cur, loc, entries)
						want, wantErr := oldFormatLedger(cur, loc, entries)
						if (gotErr == nil) != (wantErr == nil) {
							t.Fatalf("error mismatch for %s %s %v: new=%v old=%v", cur, loc, amt, gotErr, wantErr)
						}
						if gotErr != nil {
							continue
						}
						if got != want {
							t.Fatalf("output mismatch for %s %s %v %q %q\nnew:\n%q\nold:\n%q", cur, loc, amt, dt, de, got, want)
						}
						n++
					}
				}
			}
		}
	}
	t.Logf("differential: %d matching outputs", n)

	// Multi-entry: unsorted input with mixed dates/descriptions/changes.
	for _, cur := range currencies {
		for _, loc := range locales {
			entries := []Entry{
				{Date: "2015-01-02", Description: "Get present", Change: 1000},
				{Date: "2015-01-01", Description: "Buy present", Change: -1000},
				{Date: "2015-01-01", Description: "Buy present", Change: 1000},
				{Date: "2014-12-31", Description: "Year end", Change: 999999},
				{Date: "2015-01-01", Description: "Buy present", Change: -1000},
			}
			got, gotErr := FormatLedger(cur, loc, entries)
			want, wantErr := oldFormatLedger(cur, loc, entries)
			if (gotErr == nil) != (wantErr == nil) || (gotErr == nil && got != want) {
				t.Fatalf("multi-entry mismatch for %s %s\nnew:\n%q\nold:\n%q", cur, loc, got, want)
			}
		}
	}

	// Error cases: both must report an error.
	errCases := []struct {
		currency, locale string
		entries          []Entry
	}{
		{"", "en-US", nil},
		{"ABC", "en-US", nil},
		{"USD", "", nil},
		{"USD", "nl-US", nil},
		{"USD", "en-US", []Entry{{Date: "2015-131-11", Description: "x", Change: 1}}},
		{"USD", "en-US", []Entry{{Date: "2015-12/11", Description: "x", Change: 1}}},
		{"ABC", "nl-NL", []Entry{{Date: "2015-01-01", Description: "x", Change: 1}}},
	}
	for i, tc := range errCases {
		_, gotErr := FormatLedger(tc.currency, tc.locale, tc.entries)
		_, wantErr := oldFormatLedger(tc.currency, tc.locale, tc.entries)
		if (gotErr == nil) != (wantErr == nil) {
			t.Fatalf("err case %d: new err=%v old err=%v", i, gotErr, wantErr)
		}
	}
}
