// Multi-entry: the original sort compares against a STALE copy of es[0]
// (never refreshed after swaps), so it only terminates when at most one
// entry sorts before the first input entry; otherwise it loops forever.
// For 2-entry inputs it is well-defined and equals the true sort order,
// so those are safe to differential-test.
twoEntryCases := [][]Entry{
	{{Date: "2015-01-02", Description: "Get present", Change: 1000}, {Date: "2015-01-01", Description: "Buy present", Change: -1000}},
	{{Date: "2015-01-01", Description: "Buy present", Change: -1000}, {Date: "2015-01-01", Description: "Get present", Change: 1000}},
	{{Date: "2015-01-01", Description: "Buy present", Change: -1000}, {Date: "2014-12-31", Description: "Year end", Change: 999999}},
	{{Date: "2015-01-01", Description: "Buy present", Change: -1000}, {Date: "2015-01-01", Description: "Buy present", Change: 1000}},
}
for _, entries := range twoEntryCases {
	for _, cur := range currencies {
		for _, loc := range locales {
			got, gotErr := FormatLedger(cur, loc, entries)
			want, wantErr := oldFormatLedger(cur, loc, entries)
			if (gotErr == nil) != (wantErr == nil) || (gotErr == nil && got != want) {
				t.Fatalf("multi-entry mismatch for %s %s\nnew:\n%q\nold:\n%q", cur, loc, got, want)
			}
		}
	}
}

// 3+ entries: the original sort is broken (infinite loop), so only
// verify the refactored output is in true (date, description, change)
// order.
manyEntries := []Entry{
	{Date: "2015-01-02", Description: "Get present", Change: 1000},
	{Date: "2015-01-01", Description: "Buy present", Change: -1000},
	{Date: "2015-01-01", Description: "Buy present", Change: 1000},
	{Date: "2014-12-31", Description: "Year end", Change: 999999},
	{Date: "2015-01-01", Description: "Buy present", Change: -1000},
}
got, err := FormatLedger("USD", "en-US", manyEntries)
if err != nil {
	t.Fatalf("unexpected error: %v", err)
}
lines := strings.Split(strings.TrimSuffix(got, "\n"), "\n")[1:]
if len(lines) != len(manyEntries) {
	t.Fatalf("expected %d lines, got %d", len(manyEntries), len(lines))
}
for i := 1; i < len(lines); i++ {
	prev, cur := lines[i-1], lines[i]
	if prev > cur {
		t.Fatalf("lines not sorted:\n%q\n%q", prev, cur)
	}
}

